import Foundation
private struct BenchmarkSummary:Codable{let list:SchoolList;let rebuildMatches:Bool;let eventCount:Int;let checkpoint:Int;let listenerFaults:Int;let stepCounts:[String:Int];let errors:[String:Int];let conflicts:Int}
func benchmarkOutput(_ o:RunOutput)throws->Data{var steps:[String:Int]=[:],errors:[String:Int]=[:],conflicts=0;for s in o.steps{steps[s.status,default:0]+=1;for e in s.errors{errors[e.rawValue,default:0]+=1};conflicts+=s.conflicts};let encoder=JSONEncoder();encoder.outputFormatting=[.sortedKeys];let matches=try encoder.encode(o.list)==encoder.encode(o.rebuilt);return try JSONEncoder().encode(BenchmarkSummary(list:o.list,rebuildMatches:matches,eventCount:o.events.count,checkpoint:o.checkpoint,listenerFaults:o.listenerFaults,stepCounts:steps,errors:errors,conflicts:conflicts))}
